import { readOwnPackageVersion } from '@exprtlabs/golem/internal/generator-support';
import { blockComment, type Code } from '@exprtlabs/golem/internal/emitter';

export const PACKAGE_VERSION = readOwnPackageVersion(import.meta.url);
export const GENERATOR_NAME = '@exprtlabs/golem-openapi-ts';
export const API_VERSION = 1 as const;

/** The banner comment of a generated file, as Code. */
export function generatedBannerComment(): Code {
  return blockComment(`Generated by ${GENERATOR_NAME}. Do not edit.`);
}
